// Copyright (c) 2026 Roshan. All rights reserved.// Proprietary license — see LICENSE file for details.package com.roshan.persona.voice.audioimport kotlinx.coroutines.flow.Flowimport kotlinx.coroutines.flow.MutableSharedFlowimport kotlinx.coroutines.flow.asSharedFlowimport kotlinx.coroutines.flow.filter/** * NOUS — Audio Capture Pipeline. * * The entry point for all microphone audio in NOUS. Orchestrates the full * 3-layer noise cancellation chain and exposes clean audio as a [Flow]: * * ``` * Microphone → AEC → RNNoise → AGC → VAD → Output Flow *                  ↓              ↓ *               TTS echo      Background noise *               removed       removed * ``` * * ## Architecture (v2 — hardware-first) * * Per v2 fix #5, the pipeline uses hardware AEC first (AcousticEchoCanceler, * DSP-accelerated, sub-ms latency), falling back to software AEC (LMS adaptive * filter) when hardware is unavailable. * * The pipeline also runs a VAD on every chunk and tags each output with the * VAD result. Downstream consumers (wake word detector, STT, barge-in * detector) can use this tag to skip non-voice chunks (60% battery savings * for wake word detector). * * ## Privacy * *   - Audio NEVER leaves the device *   - Audio is NOT recorded to disk (only in-memory circular buffer) *   - User can pause capture at any time (Privacy Mode) *   - All audio is discarded within 2 seconds of capture (circular buffer) * * ## Lifecycle * *   1. Create with [create] (probes hardware, builds chain) *   2. Call [start] to begin capturing (foreground service required) *   3. Collect from [audioStream] (or use [addListener] for callbacks) *   4. Call [stop] to pause capture *   5. Call [release] to free native resources (microphone, audio effects) * * @see <a href="docs/strategy/module-5-strategy-v2.md">§5 Audio Capture Pipeline</a> */class AudioCapturePipeline internal constructor(    /** Echo canceller (hardware or software). */    private val echoCanceller: EchoCanceller,    /** Noise suppressor (RNNoise-style). */    private val noiseSuppressor: NoiseSuppressor,    /** Automatic gain controller. */    private val gainController: AutomaticGainController,    /** Voice activity detector. */    private val voiceActivityDetector: VoiceActivityDetector,    /** Circular pre-roll buffer (2 seconds) for wake-word context. */    val circularBuffer: CircularAudioBuffer = CircularAudioBuffer(),    /** Audio source — abstracts Android AudioRecord for testability. */    private val audioSource: AudioSource,) {    /** Whether the pipeline is currently capturing. */    @Volatile    private var capturing: Boolean = false    /** Whether this pipeline has been released. */    private var released: Boolean = false    /** Sequence counter for chunks emitted by this pipeline. */    private var nextSequence: Long = 0L    /** Last TTS reference chunk (for echo cancellation during TTS playback). */    @Volatile    private var currentTtsReference: AudioChunk? = null    /** Hot stream of processed audio chunks (with VAD results). */    private val audioFlow = MutableSharedFlow<ProcessedAudioChunk>(        replay = 0,        extraBufferCapacity = 64, // 64 chunks × 20ms = 1.28s buffer    )    /** Stream of processed audio chunks. Collectors receive all chunks. */    val audioStream: Flow<ProcessedAudioChunk> = audioFlow.asSharedFlow()    /**     * Stream of voice-only chunks (silence filtered out).     *     * Shortcut for `audioStream.filter { it.vadResult.isVoice }`.     * Useful for wake word detectors and STT engines that don't need silence.     */    val voiceStream: Flow<ProcessedAudioChunk> = audioStream        .filter { it.vadResult.isVoice }    /** Whether the pipeline is currently capturing audio. */    val isCapturing: Boolean get() = capturing    /** Whether this pipeline uses hardware AEC. */    val isUsingHardwareAec: Boolean get() = echoCanceller.isUsingHardware    /**     * Start capturing audio.     *     * Requires RECORD_AUDIO permission. The caller is responsible for ensuring     * a foreground service is active (Android 9+ requirement for background mic).     *     * @return true if capture started successfully, false if mic unavailable     */    suspend fun start(): Boolean {        check(!released) { "Cannot start after release" }        if (capturing) return true // already started        val started = audioSource.start()        if (!started) return false        // Attach hardware AEC to the audio session (if hardware AEC)        val sessionId = audioSource.audioSessionId        if (sessionId != AudioSource.NO_SESSION) {            echoCanceller.attachToSession(sessionId)        }        capturing = true        return true    }    /**     * Stop capturing audio.     *     * Releases the microphone (other apps can use it). The circular buffer     * is preserved so that the last 2 seconds of audio remain available     * for wake-word context.     */    fun stop() {        if (!capturing) return        capturing = false        audioSource.stop()    }    /**     * Process a single audio chunk from the source.     *     * This is the main processing method. The pipeline:     *   1. Applies echo cancellation (removes TTS echo from mic input)     *   2. Applies noise suppression (removes background noise)     *   3. Applies automatic gain control (normalizes volume)     *   4. Runs VAD (tags chunk with voice/silence decision)     *   5. Appends to circular buffer (for wake-word context)     *   6. Emits to [audioStream] for downstream consumers     *     * Visible for testing — production code should collect from [audioStream]     * instead of calling this directly.     *     * @param rawChunk the raw audio chunk from the microphone     * @return the processed chunk with VAD result, or null if pipeline is stopped     */    suspend fun processChunk(rawChunk: AudioChunk): ProcessedAudioChunk? {        if (!capturing) return null        // 1. Echo cancellation (remove TTS echo)        val afterAec = echoCanceller.cancelEcho(rawChunk, currentTtsReference)        // 2. Noise suppression (remove background noise)        val afterNs = noiseSuppressor.suppress(afterAec)        // 3. Automatic gain control (normalize volume)        val afterAgc = gainController.process(afterNs)        // 4. VAD (tag with voice/silence decision)        val vadResult = voiceActivityDetector.detect(afterAgc)        // 5. Append to circular buffer (for wake-word pre-roll)        circularBuffer.append(afterAgc)        // 6. Build processed chunk and emit        val processed = ProcessedAudioChunk(            audio = afterAgc,            vadResult = vadResult,            sequenceNumber = nextSequence++,            timestampMs = System.currentTimeMillis(),            pipelineStages = PipelineStages(                appliedAec = echoCanceller.isUsingHardware || currentTtsReference != null,                appliedNoiseSuppression = true,                appliedAgc = true,                appliedVad = true,            ),        )        audioFlow.emit(processed)        return processed    }    /**     * Notify the pipeline that TTS playback has started.     *     * The pipeline will use the TTS audio as a reference for echo cancellation.     * Call this immediately before TTS starts playing, and call [onTtsStopped]     * immediately after TTS finishes.     *     * @param ttsChunk the TTS audio being played (reference for echo cancellation)     */    fun onTtsPlaying(ttsChunk: AudioChunk) {        currentTtsReference = ttsChunk    }    /**     * Notify the pipeline that TTS playback has stopped.     *     * Clears the TTS reference, so echo cancellation won't try to cancel     * non-existent TTS audio.     */    fun onTtsStopped() {        currentTtsReference = null    }    /** Get a snapshot of the last 2 seconds of audio (for wake-word context). */    fun getRecentAudio(): AudioChunk = circularBuffer.snapshot()    /** Get the last N milliseconds of audio. */    fun getRecentAudio(durationMs: Int): AudioChunk = circularBuffer.snapshotLast(durationMs)    /** Reset all pipeline state (VAD, NS, AGC, circular buffer). */    fun reset() {        voiceActivityDetector.reset()        noiseSuppressor.reset()        gainController.reset()        circularBuffer.clear()        currentTtsReference = null        nextSequence = 0L    }    /** Release all native resources. After release, the pipeline is unusable. */    fun release() {        if (released) return        released = true        capturing = false        try {            audioSource.release()        } catch (e: Throwable) { /* best effort */ }        try {            echoCanceller.release()        } catch (e: Throwable) { /* best effort */ }        try {            noiseSuppressor.release()        } catch (e: Throwable) { /* best effort */ }        try {            gainController.release()        } catch (e: Throwable) { /* best effort */ }        circularBuffer.clear()    }    companion object {        /**         * Create a default audio capture pipeline.         *         * Probes hardware capabilities and configures the optimal processing chain.         *         * @param audioSource the audio source (use [DefaultAudioSource] for production,         *                    or a fake for testing)         * @param capabilities probed hardware capabilities (or null to probe now)         */        fun create(            audioSource: AudioSource,            capabilities: AudioEffectCapabilities? = null,        ): AudioCapturePipeline {            val caps = capabilities ?: AudioEffectCapabilities.probe()            return AudioCapturePipeline(                echoCanceller = EchoCanceller.create(caps),                noiseSuppressor = NoiseSuppressor(),                gainController = AutomaticGainController(),                voiceActivityDetector = VoiceActivityDetector(),                audioSource = audioSource,            )        }    }}/** * A processed audio chunk with metadata about pipeline stages. * * Emitted by [AudioCapturePipeline.audioStream]. Contains: *   - The processed audio (after AEC + NS + AGC) *   - The VAD result (voice/silence + band energies) *   - Sequence number (monotonic) *   - Timestamp (epoch milliseconds) *   - Which pipeline stages were applied */data class ProcessedAudioChunk(    /** The processed audio (post AEC + NS + AGC). */    val audio: AudioChunk,    /** VAD result for this chunk. */    val vadResult: VadResult,    /** Monotonic sequence number. */    val sequenceNumber: Long,    /** When this chunk was processed (epoch ms). */    val timestampMs: Long,    /** Which pipeline stages were applied to this chunk. */    val pipelineStages: PipelineStages,)/** * Which pipeline stages were applied to a chunk. * * Useful for diagnostics and for downstream consumers that need to know * whether echo cancellation was active (e.g., to interpret VAD results). */data class PipelineStages(    /** Whether echo cancellation was applied (hardware or software). */    val appliedAec: Boolean,    /** Whether noise suppression was applied. */    val appliedNoiseSuppression: Boolean,    /** Whether automatic gain control was applied. */    val appliedAgc: Boolean,    /** Whether VAD was run. */    val appliedVad: Boolean,)